
LAB_ENGINES.sums={
 init(c,seed){const v=c.variant,r=labRand(seed*7919),d={w:3,board:Array(9).fill(null),selected:null,undo:[],a:2+seed%5,b:3+seed%4};
 if(['regions','fit','chains'].includes(v)){d.solution=labShuffle([1,2,3,4,5,6,7,8,9],r);d.tiles=labShuffle(d.solution,r);d.regions=v==='regions'?[[0,1,3,4],[1,2,4,5],[3,4,6,7],[4,5,7,8]]:v==='chains'?[[0,1,4],[2,5,8],[3,6,7]]:[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8]];d.targets=d.regions.map(a=>a.reduce((sum,i)=>sum+d.solution[i],0));}
 if(v==='stacks'){d.stacks=[{value:d.a,op:'+',used:false},{value:d.b,op:'+',used:false},{value:2,op:'×',used:false},{value:1,op:'−',used:false}];d.targets=[d.a*2,d.b-1];}
 if(v==='out'){d.board=labShuffle([1,-1,2,-2,3,-3,4,-4,0],r);d.selected=[];}
 if(v==='stretch'||v==='magnet'){d.w=5;d.board=Array(25).fill(0);d.board[0]=v==='stretch'?6:4;d.board[4]=v==='stretch'?-2:-4;d.board[20]=v==='stretch'?6:3;d.board[24]=v==='stretch'?-2:-3;d.selected=null;d.fixed=[4,24];}
 if(v==='hex'){d.w=3;d.solution=[1,0,1,1,0,0,1];d.board=Array(7).fill(0);d.neighbours=[[1,2,3,4,5,6],[0,2,6],[0,1,3],[0,2,4],[0,3,5],[0,4,6],[0,5,1]];d.targets=d.neighbours.map(a=>a.filter(i=>d.solution[i]).length);}
 if(v==='billy'){d.w=5;d.board=Array(25).fill(0);d.pos=10;d.box=11;d.goal=14;d.walls=[1,2,3,6,7,8,16,17,18,21,22,23];d.value=d.a;d.operator='+';d.target=d.a+d.b;d.answer=null;}
 return d;
 },
 render(d,c){const v=c.variant;if(['regions','fit','chains'].includes(v))return '<p>Select a number tile, then a square. Use every tile once. '+(v==='chains'?'Each coloured chain must match its target.':v==='regions'?'Overlapping regions share their numbers.':'Meet the row and column targets.')+'</p><div class="lab-clues">'+d.regions.map((a,k)=>'<p style="color:'+LAB_COLORS[k%6]+'">'+a.map(i=>i+1).join(' + ')+' → target '+d.targets[k]+'</p>').join('')+'</div>'+labGrid(d.board,3,(v,i)=>v??'<small>#'+(i+1)+'</small>')+labOptions('tile',d.tiles)+labButton('check','Check sums');
 if(v==='stacks')return '<div class="lab-callout">Build two stacks: '+d.targets.join(' and ')+'</div><p>Choose a tile to move, then a destination. The moving tile’s operation acts on the destination value. Order matters!</p><div class="lab-options">'+d.stacks.map((t,i)=>labButton('stack',t.op+' '+t.value,i,t.used)).join('')+'</div>'+labButton('check','Check stacks')+labButton('undo','Undo stack');
 if(v==='out')return '<p>Select a group of numbers with a total of zero, then remove them. Clear every tile.</p>'+labGrid(d.board,3,(x,i)=>x===null?'·':'<span class="'+(d.selected.includes(i)?'lab-selected':'')+'">'+(x>0?'+':'')+x+'</span>')+labButton('remove','Remove zero group');
 if(v==='stretch'||v==='magnet')return '<p>'+(v==='stretch'?'Select a positive tile, then a destination in its row or column. It loses one per square travelled. Land on a negative to cancel it exactly.':'Select a positive magnet, then an equal negative tile in the same row or column. A clear line pulls them together and cancels them.')+'</p>'+labGrid(d.board,5,x=>x?'<b style="color:'+(x>0?'#b3436e':'#267eae')+'">'+(x>0?'+':'')+x+'</b>':'·')+labButton('undo','Undo');
 if(v==='hex')return '<p>Toggle the seven hexagons. Each clue shows how many neighbouring hexagons must be filled.</p><div class="lab-hex-board">'+d.board.map((x,i)=>labButton('hex','<span style="background:'+(x?'#9463c7':'#e9dffa')+'">'+d.targets[i]+'</span>',i)).join('')+'</div>'+labButton('check','Check neighbours');
 return '<p>Push the number crate to the flag. At the flag, complete the equation to open the exit.</p>'+labGrid(d.board,5,(_,i)=>d.pos===i?'🧑‍🚀':d.box===i?d.value:i===d.goal?'🏁':d.walls.includes(i)?'⬛':'·')+labOptions('move',['↑','→','↓','←'])+(d.box===d.goal?'<form id="lab-form"><label>'+d.value+' + <input id="lab-number" type="number" aria-label="Missing number"> = '+d.target+'</label><button class="button primary">Open exit</button></form>':'');
 },
 action(d,a,n,c){const v=c.variant,save=()=>{const copy={...d};delete copy.undo;d.undo.push(JSON.stringify(copy));};if(a==='undo'&&d.undo.length){Object.assign(d,JSON.parse(d.undo.pop()));return;}
 if(['regions','fit','chains'].includes(v)){if(a==='tile'){d.selected=n;return;}if(a==='cell'&&d.selected!==null){const value=d.tiles[d.selected],old=d.board.indexOf(value);if(old>=0)d.board[old]=d.board[n];d.board[n]=value;d.selected=null;game.session.moves++;}if(a==='check'){if(d.board.every(x=>x!==null)&&new Set(d.board).size===9&&d.regions.every((ids,k)=>ids.reduce((s,i)=>s+d.board[i],0)===d.targets[k]))labWin('All sums agree!');else labMiss('One or more targets still need adjusting.');}return;}
 if(v==='stacks'){if(a==='stack'&&!d.stacks[n]?.used){if(d.selected===null){d.selected=n;return;}if(d.selected===n){d.selected=null;return;}save();const from=d.stacks[d.selected],to=d.stacks[n];to.value=from.op==='+'?to.value+from.value:from.op==='−'?to.value-from.value:to.value*from.value;from.used=true;d.selected=null;game.session.moves++;}if(a==='check'){const values=d.stacks.filter(t=>!t.used).map(t=>t.value).sort((a,b)=>a-b);if(values.join()===d.targets.slice().sort((a,b)=>a-b).join())labWin('Both target stacks built!');else labMiss('Use the operations in another order.');}return;}
 if(v==='out'){if(a==='cell'&&d.board[n]!==null)d.selected=d.selected.includes(n)?d.selected.filter(i=>i!==n):[...d.selected,n];if(a==='remove'){if(!d.selected.length||d.selected.reduce((s,i)=>s+d.board[i],0)!==0){labMiss('Choose numbers that balance to zero.');return;}d.selected.forEach(i=>d.board[i]=null);d.selected=[];game.session.moves++;if(d.board.every(x=>x===null))labWin('A perfectly balanced empty board!');}return;}
 if((v==='stretch'||v==='magnet')&&a==='cell'){if(d.board[n]>0){d.selected=n;return;}if(d.selected===null)return;const from=d.selected,dx=n%5-from%5,dy=Math.floor(n/5)-Math.floor(from/5);if(dx&&dy||!dx&&!dy)return;const distance=Math.abs(dx+dy),dir=dx?dx>0?1:3:dy>0?2:0;let at=labNeighbour(from,dir,5);while(at!==n){if(d.board[at]){labMiss('The path is blocked.');return;}at=labNeighbour(at,dir,5);}const value=d.board[from]-(v==='stretch'?distance:0);if(v==='magnet'&&!d.board[n]||value<=0||d.board[n]&&value+d.board[n]!==0){labMiss('The values must cancel exactly after the move.');return;}save();d.board[from]=0;d.board[n]=d.board[n]?0:value;d.selected=null;game.session.moves++;if(d.board.every(x=>x===0))labWin('All charges cancelled!');return;}
 if(v==='hex'){if(a==='hex')d.board[n]=1-d.board[n];if(a==='check'){if(d.neighbours.every((ids,i)=>ids.filter(k=>d.board[k]).length===d.targets[i]))labWin('Every hex clue is satisfied!');else labMiss('Count only the neighbours of each hexagon.');}return;}
 if(v==='billy'){if(a==='move'){const next=labNeighbour(d.pos,n,5);if(next<0||d.walls.includes(next))return;if(next===d.box){const beyond=labNeighbour(next,n,5);if(beyond<0||d.walls.includes(beyond))return;d.box=beyond;}d.pos=next;game.session.moves++;}if(a==='submit'){if(d.box===d.goal&&Number($('#lab-number').value)===d.b)labWin('The equation opened the exit!');else labMiss('Check the missing addend.');}}
 }
};
